import { unwrapCodeSpans } from "@ai-matrx/content-ir/source";
import { dataRowIndexes, rowCells } from "../../../utils/table-source.js";
import { isGfmDelimiterRow } from "../../markdown-classification/processors/utils/gfm-table-lines.js";
function cleanTableHeaderKey(header) {
  return unwrapCodeSpans(header).replace(/\*\*([^*]+)\*\*/g, "$1").replace(/\*([^*]+)\*/g, "$1").replace(/(?<![A-Za-z0-9])_([^_\n]+?)_(?![A-Za-z0-9])/g, "$1").replace(/\[([^\]]+)\]\(([^)]+)\)/g, "$1|$2").trim();
}
function parseMarkdownTable(content) {
  try {
    const lines = content.split("\n").filter((line) => line.trim().length > 0);
    if (lines.length < 2) return null;
    const headerLine = lines[0];
    const separatorLine = lines[1];
    if (!isGfmDelimiterRow(separatorLine)) return null;
    const parseRow = rowCells;
    const headers = parseRow(headerLine);
    if (headers.length === 0) return null;
    const dataLines = lines.slice(2);
    const validRows = dataRowIndexes(dataLines, dataLines.map((_line, index) => index)).map((index) => parseRow(dataLines[index] ?? ""));
    const normalizedData = validRows.map((row) => {
      const rowData = {};
      headers.forEach((header, index) => {
        rowData[cleanTableHeaderKey(header)] = index < row.length ? row[index] : "";
      });
      return rowData;
    });
    return { headers, rows: validRows, normalizedData };
  } catch (error) {
    console.error("[parseMarkdownTable] Parse error:", error);
    return null;
  }
}
export {
  cleanTableHeaderKey,
  parseMarkdownTable
};
