import { useRef } from "react";
function useDoubleClickEdit({
  canEnterEditMode,
  editMode,
  setEditMode
}) {
  const pendingFocusRef = useRef(null);
  const handleTableDoubleClick = (e) => {
    if (!canEnterEditMode) return;
    const target = e.target;
    if (!target) return;
    if (target.closest("input, textarea, button")) return;
    const cell = target.closest("[data-cell]");
    if (!cell) return;
    const kind = cell.dataset.cell;
    if (kind === "header") {
      if (editMode !== "header") setEditMode("header");
      return;
    }
    if (kind === "body") {
      const row = Number(cell.dataset.cellRow);
      const col = Number(cell.dataset.cellCol);
      if (Number.isNaN(row) || Number.isNaN(col)) return;
      if (editMode === row) {
        const textarea = cell.querySelector("textarea");
        if (textarea) {
          textarea.focus();
          textarea.select();
        }
        return;
      }
      pendingFocusRef.current = { row, col };
      setEditMode(row);
    }
  };
  const bindCellTextareaRef = (rowIndex, colIndex) => (el) => {
    if (!el) return;
    const pending = pendingFocusRef.current;
    if (!pending) return;
    if (pending.row !== rowIndex || pending.col !== colIndex) return;
    pendingFocusRef.current = null;
    requestAnimationFrame(() => {
      el.focus();
      el.select();
    });
  };
  return { handleTableDoubleClick, bindCellTextareaRef };
}
export {
  useDoubleClickEdit
};
